          "ja": "アンドラ観光局は、伝統的アンドラ料理の認証店の一つとしてCan Manelを掲載しています。同局によると、トリンシャットは冬キャベツ、ジャガイモ、ニンニク、豚脂を使うピレネー地方の料理です。現在の営業時間とメニューは未確認です。",
          "ko": "안도라 관광청은 칸 마넬을 전통 안도라 요리 인증을 받은 식당 중 하나로 소개합니다. 관광청 설명에 따르면 트린사트는 겨울 양배추·감자·마늘·돼지고기 지방을 넣는 피레네 전통 요리입니다. 현재 영업시간과 메뉴는 확인되지 않았습니다.",
          "zh": "安道尔旅游局将Can Manel列为获得“安道尔传统料理”认证的餐厅之一。旅游局介绍，山地土豆甘蓝泥是以冬季甘蓝、土豆、大蒜和猪脂制成的比利牛斯传统菜；当前营业时间及菜单未核实。"
