              "zh": "安道尔的山地饮食既体现季节食材，也受到加泰罗尼亚和法国烹饪的影响。特林沙特和埃斯库德利亚是具有代表性的冬季菜肴，烤制奶油汁肉卷也属于当地传统菜式。"
