        "ja": "平坦な市街地の展望台ではなく、山道のハイキングコースです。公式案内では全行程約9km、所要3～6時間、累積上昇約640m・下降約610mです。暗い時間帯の利用を検討する場合は、道の状態や天候、下山計画を確認してください。安全を保証するものではありません。",
        "ko": "도심의 평탄한 전망대가 아니라 산길 하이킹 코스입니다. 공식 안내의 전체 코스는 약 9km, 3–6시간, 누적 상승·하강 약 640m/610m로 기재되어 있습니다. 어두운 시간대에는 노면·날씨와 하산 계획을 확인해야 하며, 안전을 보장할 수 없습니다.",
