          "ja": "夕方の市内移動には、地下鉄1号線でトレドからミュニチピオ、ウニヴェルシタ、ドゥオーモの順に進めます。チェントロ・ディレツィオナーレ方面へ中間2駅、3区間です。ANMはトレド駅とドゥオーモ駅の芸術作品を紹介しています。深夜まで駅や列車が運行する保証ではありません。運行時刻とお知らせは当日にANMで確認してください。",
