          "zh": "傍晚在市内乘坐1号线，可从托莱多经市政厅站、大学站到主教座堂站，朝中央商务区方向经过2个中间站，共3段站间行程。ANM介绍了托莱多站和主教座堂站的艺术装置。这不代表车站或列车会运营至深夜；请在当天查看ANM最新时刻表和服务通知。"
