        "ja": "川を見下ろす高台にあり、周辺の川岸斜面は急です。経路によっては上り坂や高低差があるため、出発地点からのルートを確認してください。",
        "ko": "강 위쪽의 높은 지대에 있으며 주변 강변 사면은 가파릅니다. 접근 경로에 따라 고도 차와 오르막이 있을 수 있으니, 출발 지점별 보행 조건을 확인하세요.",
        "zh": "观景台位于河岸上方的高地，附近河岸坡面较陡。不同路线可能有爬坡和高低差，请按出发地点确认路线情况。"
